  for k in ['strand_id']:
   if c.get(k) and c[k] not in ids:
    # Use exact title lookup for the three human-friendly references.
    lookup={'space_capital_cultural_city':'Space, capital and the cultural city','race_industrial_change':'Race and industrial change','comparative_settler_colonies':'Comparative and twentieth-century settler colonies'}
